// Package gen defines generation interfaces for images (book covers), music (BGM) and sound
// effects. Images are generated by OpenAI GPT Image or Google Nano Banana, music by Suno (through
// relays speaking the Suno-API protocol); the other third-party adapters are reserved stubs. Built-in placeholder generators produce procedural results so the
// product flows work before real adapters are connected.
package gen

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"image"
	"image/color"
	"image/png"
	"math"
	"math/rand"

	"voicebook/internal/audio"
)

var ErrNotImplemented = errors.New("该平台的生成适配器为预留接口，尚未实现")

type Account struct {
	Provider string
	BaseURL  string
	APIKey   string
	Model    string
	Config   map[string]any
}

type File struct {
	Data []byte
	Mime string
	Ext  string
	Meta map[string]any
}

// ---------------- Images ----------------

type ImageRequest struct {
	Prompt   string
	Negative string
	Style    string
	Width    int
	Height   int
	Aspect   string // "1:1", "3:4" …; derived from Width/Height when empty
	Count    int
	Seed     string
	User     string // stable hashed end-user id, for the vendor's abuse monitoring
}

type ImageProvider interface {
	Name() string
	GenerateImage(ctx context.Context, r ImageRequest) ([]File, error)
}

// ---------------- Music ----------------

type MusicRequest struct {
	Prompt       string // what the music should be like
	DurationMs   int    // honoured by providers whose MusicFeatures.Duration is true
	Instrumental bool
	Loopable     bool
	Seed         string
	Title        string // songs: the title (optional)
	Lyrics       string // songs: lyrics to sing; empty lets the provider write them
	Style        string // songs: style tags such as "古风, 钢琴, 女声"
	OnTask       func(taskID string)
}

type MusicProvider interface {
	Name() string
	GenerateMusic(ctx context.Context, r MusicRequest) (*File, error)
}

// ---------------- Sound effects ----------------

type SFXRequest struct {
	Prompt     string
	DurationMs int
	Seed       string
}

type SFXProvider interface {
	Name() string
	GenerateSFX(ctx context.Context, r SFXRequest) (*File, error)
}

func NewImage(a Account) (ImageProvider, error) {
	switch a.Provider {
	case "placeholder":
		return placeholder{}, nil
	case "openai_image":
		return newOpenAIImage(a), nil
	case "gemini_image":
		return newGeminiImage(a), nil
	case "tongyi_wanxiang", "doubao_seedream", "stability", "midjourney", "selfhost_sd":
		return stub(a.Provider), nil
	}
	return nil, fmt.Errorf("未知的图片生成平台：%s", a.Provider)
}

func NewMusic(a Account) (MusicProvider, error) {
	switch a.Provider {
	case "placeholder":
		return placeholder{}, nil
	case "suno":
		return newSuno(a), nil
	case "elevenlabs_music", "minimax_music", "mubert", "stability_audio":
		return stub(a.Provider), nil
	}
	return nil, fmt.Errorf("未知的音乐生成平台：%s", a.Provider)
}

func NewSFX(a Account) (SFXProvider, error) {
	switch a.Provider {
	case "placeholder":
		return placeholder{}, nil
	case "elevenlabs_sfx", "stability_audio", "audiogen":
		return stub(a.Provider), nil
	}
	return nil, fmt.Errorf("未知的音效生成平台：%s", a.Provider)
}

type stub string

func (s stub) Name() string { return string(s) }
func (s stub) GenerateImage(context.Context, ImageRequest) ([]File, error) {
	return nil, ErrNotImplemented
}
func (s stub) GenerateMusic(context.Context, MusicRequest) (*File, error) {
	return nil, ErrNotImplemented
}
func (s stub) GenerateSFX(context.Context, SFXRequest) (*File, error) { return nil, ErrNotImplemented }

type placeholder struct{}

func (placeholder) Name() string { return "placeholder" }

func wavFile(p *audio.PCM, meta map[string]any) (*File, error) {
	var buf bytes.Buffer
	if err := audio.EncodeWAV16(&buf, p); err != nil {
		return nil, err
	}
	return &File{Data: buf.Bytes(), Mime: "audio/wav", Ext: "wav", Meta: meta}, nil
}

func (placeholder) GenerateMusic(ctx context.Context, r MusicRequest) (*File, error) {
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	dur := r.DurationMs
	if dur <= 0 {
		dur = 60000
	}
	if dur > 180000 {
		dur = 180000
	}
	p, mood := audio.GenerateMusic(r.Prompt, dur, audio.Seed(r.Seed, r.Prompt))
	return wavFile(p, map[string]any{"mood": mood})
}

func (placeholder) GenerateSFX(ctx context.Context, r SFXRequest) (*File, error) {
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	p, kind := audio.GenerateSFX(r.Prompt, r.DurationMs, audio.Seed(r.Seed, r.Prompt))
	return wavFile(p, map[string]any{"kind": kind})
}

// palettes for the abstract cover generator
var palettes = [][]color.RGBA{
	{{0x1b, 0x1f, 0x3b, 255}, {0x4f, 0x46, 0xe5, 255}, {0xf4, 0x72, 0xb6, 255}, {0xfd, 0xe6, 0x8a, 255}},
	{{0x0f, 0x17, 0x2a, 255}, {0x0e, 0xa5, 0xe9, 255}, {0x22, 0xd3, 0xee, 255}, {0xe0, 0xf2, 0xfe, 255}},
	{{0x1c, 0x19, 0x17, 255}, {0xb4, 0x53, 0x09, 255}, {0xf5, 0x9e, 0x0b, 255}, {0xfe, 0xf3, 0xc7, 255}},
	{{0x0b, 0x1f, 0x16, 255}, {0x05, 0x96, 0x69, 255}, {0x86, 0xef, 0xac, 255}, {0xec, 0xfd, 0xf5, 255}},
	{{0x2e, 0x10, 0x65, 255}, {0x7c, 0x3a, 0xed, 255}, {0xc0, 0x84, 0xfc, 255}, {0xfa, 0xe8, 0xff, 255}},
	{{0x26, 0x0a, 0x0a, 255}, {0xb9, 0x1c, 0x1c, 255}, {0xfb, 0x71, 0x85, 255}, {0xff, 0xe4, 0xe6, 255}},
	{{0x11, 0x18, 0x27, 255}, {0x37, 0x41, 0x51, 255}, {0x9c, 0xa3, 0xaf, 255}, {0xf3, 0xf4, 0xf6, 255}},
}

// GenerateImage paints an abstract gradient artwork (no text) seeded by the prompt.
func (placeholder) GenerateImage(ctx context.Context, r ImageRequest) ([]File, error) {
	w, h := r.Width, r.Height
	if w <= 0 {
		w = 1200
	}
	if h <= 0 {
		h = 1200
	}
	n := r.Count
	if n <= 0 {
		n = 1
	}
	var out []File
	for k := 0; k < n; k++ {
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		rng := rand.New(rand.NewSource(audio.Seed(r.Seed, r.Prompt, fmt.Sprint(k))))
		pal := palettes[rng.Intn(len(palettes))]
		img := image.NewRGBA(image.Rect(0, 0, w, h))
		type blob struct {
			x, y, rad float64
			c         color.RGBA
		}
		var blobs []blob
		for i := 0; i < 5; i++ {
			blobs = append(blobs, blob{rng.Float64() * float64(w), rng.Float64() * float64(h), (0.25 + rng.Float64()*0.45) * float64(w), pal[1+rng.Intn(len(pal)-1)]})
		}
		ringX, ringY := float64(w)*(0.3+rng.Float64()*0.4), float64(h)*(0.3+rng.Float64()*0.4)
		ringFreq := 0.02 + rng.Float64()*0.03
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				t := float64(y) / float64(h)
				rr := float64(pal[0].R)*(1-t) + float64(pal[1].R)*t*0.35
				gg := float64(pal[0].G)*(1-t) + float64(pal[1].G)*t*0.35
				bb := float64(pal[0].B)*(1-t) + float64(pal[1].B)*t*0.35
				for _, b := range blobs {
					d := math.Hypot(float64(x)-b.x, float64(y)-b.y) / b.rad
					a := math.Exp(-d * d * 2.2)
					rr = rr*(1-a*0.7) + float64(b.c.R)*a*0.7
					gg = gg*(1-a*0.7) + float64(b.c.G)*a*0.7
					bb = bb*(1-a*0.7) + float64(b.c.B)*a*0.7
				}
				// subtle sound-wave rings
				d := math.Hypot(float64(x)-ringX, float64(y)-ringY)
				ring := 0.5 + 0.5*math.Sin(d*ringFreq)
				fade := math.Exp(-d / (float64(w) * 0.55))
				lift := ring * fade * 14
				grain := (rng.Float64() - 0.5) * 10
				img.SetRGBA(x, y, color.RGBA{clamp(rr + lift + grain), clamp(gg + lift + grain), clamp(bb + lift + grain), 255})
			}
		}
		var buf bytes.Buffer
		if err := png.Encode(&buf, img); err != nil {
			return nil, err
		}
		out = append(out, File{Data: buf.Bytes(), Mime: "image/png", Ext: "png"})
	}
	return out, nil
}

func clamp(v float64) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(v)
}
